import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import ArticlePageComponent from '../components/news/ArticlePage';
import { newsService } from '../services/newsService';

const ArticlePage = () => {
  const { id } = useParams();
  const [article, setArticle] = useState(null);

  useEffect(() => {
    const load = async () => {
      // Placeholder: news service may not support single article
      const data = await newsService.fetchNews({ page: 1 });
      // pick first item for now
      setArticle(data.results?.[0] || {});
    };
    load();
  }, [id]);

  return <ArticlePageComponent article={article || {}} />;
};

export default ArticlePage;
